INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.fpkt65d4',1790960928679,'41000132',NULL,NULL,1790961689552,'41000132',NULL,NULL,1,'{"sql":"SELECT ''사용 시간'' AS LABEL, ROUND(COALESCE(SUM(DURATION_MS), 0) / 60000.0, 1) AS VAL, ''분'' AS UNIT\n  FROM TB_SEC_SCREEN_USAGE_LOG WHERE STARTED_AT >= DATE(''now'', ''localtime'')\nUNION ALL\nSELECT ''사용자'', COUNT(DISTINCT USER_ID), ''명''\n  FROM TB_SEC_SCREEN_USAGE_LOG WHERE STARTED_AT >= DATE(''now'', ''localtime'')\nUNION ALL\nSELECT ''연 화면'', COUNT(DISTINCT PAGE_ID), ''개''\n  FROM TB_SEC_SCREEN_USAGE_LOG WHERE STARTED_AT >= DATE(''now'', ''localtime'')\nUNION ALL\nSELECT ''열람 횟수'', COUNT(*), ''회''\n  FROM TB_SEC_SCREEN_USAGE_LOG WHERE STARTED_AT >= DATE(''now'', ''localtime'')","labelField":"LABEL","valueField":"VAL","unitField":"UNIT","format":"number","unit":"분"}','mcm',6,12,'오늘 포털 화면 사용 시간·사용자 수·연 화면 수·열람 횟수(샘플).','mcm:csa/screenUsageStat',NULL,NULL,NULL,NULL,'N',120,'D','전체 사용자 기준','오늘 화면 사용 요약','query-number','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.jbv5t058',1790960929661,'41000132',NULL,NULL,1791211145046,'41000132',NULL,NULL,1,'{"base":"KRW","currencies":["USD","EUR","JPY","CNY","GBP"],"days":30}',NULL,10,8,'USD·EUR·JPY·CNY·GBP 원화 환율과 전일 대비(샘플).',NULL,NULL,NULL,NULL,NULL,'N',3600,'D','원화 기준 · 30일 추이','주요 환율','exchange','Y',NULL,'N',NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.jksozc87',1790960929562,'41000132',NULL,NULL,1790960929562,'41000132',NULL,NULL,0,'{"markdown":"### 홈 화면 위젯\n\n- **[배치 편집]** 에서 위젯을 추가하고, 끌어서 옮기고, 모서리로 크기를 바꿉니다.\n- 제목 줄의 아이콘으로 연결된 화면을 엽니다.\n- 관리자는 **위젯 관리** 화면에서 SQL·환율·날씨 위젯을 직접 만듭니다.\n\n> 이 위젯은 샘플입니다."}',NULL,10,8,'홈 화면 위젯 사용법 안내 글(샘플).',NULL,NULL,NULL,NULL,NULL,'N',NULL,'D',NULL,'홈 화면 위젯 안내','markdown','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.ju8bdkcr',1791204513146,'41000132',NULL,NULL,1791204513146,'41000132',NULL,NULL,0,'{"scope":"personal","format":"text","content":""}',NULL,10,8,NULL,NULL,NULL,NULL,NULL,NULL,'Y',NULL,'D',NULL,'메모장','memo','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.ldj2hpgw',1790960928815,'41000132',NULL,NULL,1790960928815,'41000132',NULL,NULL,0,'{"sql":"SELECT SUBSTR(l.STARTED_AT, 1, 16) AS STARTED,\n       COALESCE(o.OBJECT_NM, l.PAGE_ID) AS SCREEN_NM,\n       ROUND(l.DURATION_MS / 1000.0) AS SEC\n  FROM TB_SEC_SCREEN_USAGE_LOG l\n  LEFT JOIN TB_MCM_SEC_OBJ o\n    ON o.OBJECT_ID = SUBSTR(l.PAGE_ID, INSTR(l.PAGE_ID, ''/'') + 1)\n WHERE l.USER_ID = :userId\n ORDER BY l.STARTED_AT DESC\n LIMIT 20","columns":[{"field":"STARTED","header":"시작","width":130},{"field":"SCREEN_NM","header":"화면","width":160},{"field":"SEC","header":"사용(초)","width":80,"format":"number"}]}','mcm',12,12,'로그인한 사용자(:userId)의 최근 화면 사용 기록(샘플).','mcm:csa/screenUsageStat',NULL,NULL,NULL,NULL,'N',120,'D','최근 20건','내 최근 화면 사용','query-table','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.lo41tduo',1790960087937,'41000132',NULL,NULL,1790960087937,'41000132',NULL,NULL,0,'{"sql":"SELECT COALESCE(o.OBJECT_NM, l.PAGE_ID) AS SCREEN_NM,\n       ROUND(SUM(l.DURATION_MS) / 60000.0, 1) AS USE_MIN,\n       COUNT(*) AS OPEN_CNT\n  FROM TB_SEC_SCREEN_USAGE_LOG l\n  LEFT JOIN TB_MCM_SEC_OBJ o\n    ON o.OBJECT_ID = SUBSTR(l.PAGE_ID, INSTR(l.PAGE_ID, ''/'') + 1)\n WHERE l.STARTED_AT >= DATE(''now'', ''localtime'', ''-6 day'')\n GROUP BY COALESCE(o.OBJECT_NM, l.PAGE_ID)\n ORDER BY USE_MIN DESC\n LIMIT 10","chartType":"bar","xField":"SCREEN_NM","series":[{"field":"USE_MIN","label":"사용 시간(분)"}]}','mcm',12,12,'최근 7일 동안 사용 시간이 긴 화면 10개를 막대 차트로 보인다(TB_SEC_SCREEN_USAGE_LOG 집계).','mcm:csa/screenUsageStat',NULL,NULL,NULL,NULL,'N',300,'D','최근 7일 · 사용 시간(분)','화면 사용 순위','query-chart','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.oinlra77',1790960929634,'41000132',NULL,NULL,1790960929634,'41000132',NULL,NULL,0,'{"items":[{"label":"화면 사용 통계","kind":"page","pageId":"mcm:csa/screenUsageStat"},{"label":"위젯 관리","kind":"page","pageId":"mcm:csa/commWidgetMng"},{"label":"사용자 관리","kind":"page","pageId":"mcm:csa/commUserMng"},{"label":"메뉴 관리","kind":"page","pageId":"mcm:csa/commMenuMng"},{"label":"Open-Meteo (날씨 데이터)","kind":"url","url":"https://open-meteo.com"},{"label":"Frankfurter (환율 데이터)","kind":"url","url":"https://frankfurter.dev"}]}',NULL,10,6,'자주 여는 관리 화면과 데이터 출처 링크(샘플).',NULL,NULL,NULL,NULL,NULL,'N',NULL,'D',NULL,'관리자 바로가기','links','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.qcondsmp',1791206784631,'coord-sample',NULL,NULL,1791206784631,'coord-sample',NULL,NULL,0,'{"sql": "SELECT SUBSTR(l.STARTED_AT, 1, 16) AS STARTED,\n       COALESCE(o.OBJECT_NM, l.PAGE_ID) AS SCREEN_NM,\n       l.USER_ID AS USER_ID,\n       ROUND(l.DURATION_MS / 1000.0) AS SEC\n  FROM TB_SEC_SCREEN_USAGE_LOG l\n  LEFT JOIN TB_MCM_SEC_OBJ o\n    ON o.OBJECT_ID = SUBSTR(l.PAGE_ID, INSTR(l.PAGE_ID, ''/'') + 1)\n WHERE (:scope = ''ALL'' OR l.USER_ID = :userId)\n   AND (:screenNm IS NULL OR COALESCE(o.OBJECT_NM, l.PAGE_ID) LIKE ''%'' || :screenNm || ''%'')\n   AND (:fromDt IS NULL OR REPLACE(SUBSTR(l.STARTED_AT, 1, 10), ''-'', '''') >= :fromDt)\n   AND (:minSec IS NULL OR l.DURATION_MS >= :minSec * 1000)\n ORDER BY l.STARTED_AT DESC\n LIMIT 100", "params": [{"name": "scope", "label": "범위", "type": "select", "default": "MINE", "required": true, "options": [{"value": "MINE", "label": "내 기록"}, {"value": "ALL", "label": "전체 사용자"}]}, {"name": "screenNm", "label": "화면명", "type": "text"}, {"name": "fromDt", "label": "시작일", "type": "date"}, {"name": "minSec", "label": "최소 사용(초)", "type": "number", "default": "10"}], "columns": [{"field": "STARTED", "header": "시작", "width": 130}, {"field": "SCREEN_NM", "header": "화면", "width": 160}, {"field": "USER_ID", "header": "사용자", "width": 90}, {"field": "SEC", "header": "사용(초)", "width": 80, "format": "number"}]}','mcm',12,14,'입력 조건 위젯 샘플. 위쪽 조건 줄에서 범위(내 기록/전체)·화면명(부분 일치)·시작일·최소 사용(초)을 고르고 [검색]을 누르면 화면 사용 기록을 다시 조회한다. 빈 조건은 전체로 본다.','mcm:csa/screenUsageStat',NULL,NULL,NULL,NULL,'N',120,'D','범위·화면명·시작일·최소 사용 초로 조회','화면 사용 기록 검색(입력 조건 샘플)','query-table','Y','INFO','N',NULL);
