INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.smxkp6f6',1790960929715,'41000132',NULL,NULL,1790961061368,'41000132',NULL,NULL,1,'{"html":"<div style=\"padding:12px 16px;border-radius:8px;background:linear-gradient(90deg,#1e3a8a,#2563eb);color:#fff;font-family:inherit\"><div style=\"font-size:15px;font-weight:700;margin-bottom:4px\">정기 점검 안내 (샘플)</div><div style=\"font-size:13px;line-height:1.5\">매월 둘째 일요일 02:00~06:00 에 포털 점검이 있습니다.<br>작업 중인 내용은 미리 저장해 주세요.</div></div>","allowScript":true}',NULL,6,8,'html 로 꾸민 안내 배너 예시(샘플). 색·배경 같은 inline style 은 격리 iframe 모드(스크립트 허용)에서만 보인다.',NULL,NULL,NULL,NULL,NULL,'N',NULL,'D',NULL,'점검 안내 배너 (샘플)','html','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.spzufhgo',1790960929538,'41000132',NULL,NULL,1790960929538,'41000132',NULL,NULL,0,'{"sql":"SELECT CASE o.SYSTEM_CODE WHEN ''mcm'' THEN ''공통관리'' WHEN ''mdm'' THEN ''마루 MDM'' ELSE COALESCE(o.SYSTEM_CODE, ''기타'') END AS AREA,\n       ROUND(SUM(l.DURATION_MS) / 60000.0, 1) AS USE_MIN\n  FROM TB_SEC_SCREEN_USAGE_LOG l\n  LEFT JOIN TB_MCM_SEC_OBJ o\n    ON o.OBJECT_ID = SUBSTR(l.PAGE_ID, INSTR(l.PAGE_ID, ''/'') + 1)\n WHERE l.STARTED_AT >= DATE(''now'', ''localtime'', ''-29 day'')\n GROUP BY 1\n ORDER BY 2 DESC","chartType":"pie","xField":"AREA","series":[{"field":"USE_MIN","label":"사용 시간(분)"}]}','mcm',12,8,'화면 객체의 시스템 코드로 묶은 업무 영역별 사용 시간 비율(샘플).',NULL,NULL,NULL,NULL,NULL,'N',600,'D','최근 30일 · 사용 시간','업무 영역별 사용 비율','query-chart','Y',NULL,NULL,NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.u4064sz8',1790991735677,'41000132',NULL,NULL,1791299313810,'41000132',NULL,NULL,1,'{"showHistory":true}',NULL,12,13,'사칙연산 계산기(샘플)',NULL,NULL,NULL,NULL,NULL,'Y',NULL,'D',NULL,'계산기','calculator','Y',NULL,'N',NULL);
INSERT INTO "TB_MCM_WIDGET_DEF"("WIDGET_ID","C_AT","C_USR_ID","C_PGM_ID","C_SVC_ID","U_AT","U_USR_ID","U_PGM_ID","U_SVC_ID","VER","CONFIG_JSON","DATA_SRC","DEF_H","DEF_W","DESCRIPTION","LINK_PAGE_ID","MAX_H","MAX_W","MIN_H","MIN_W","MULTIPLE_YN","REFRESH_SEC","SRC_TP","SUBTITLE","TITLE","TYPE_ID","USE_YN","CATEGORY_CD","PRIVATE_YN","PLACE_TP") VALUES('def.ubb8dih0',1790960929378,'41000132',NULL,NULL,1790960929378,'41000132',NULL,NULL,0,'{"sql":"SELECT SUBSTR(STARTED_AT, 6, 5) AS DAY,\n       ROUND(SUM(DURATION_MS) / 60000.0, 1) AS USE_MIN\n  FROM TB_SEC_SCREEN_USAGE_LOG\n WHERE STARTED_AT >= DATE(''now'', ''localtime'', ''-13 day'')\n GROUP BY SUBSTR(STARTED_AT, 1, 10)\n ORDER BY SUBSTR(STARTED_AT, 1, 10)","chartType":"line","xField":"DAY","series":[{"field":"USE_MIN","label":"사용 시간(분)"}]}','mcm',12,12,'최근 14일 동안 날짜별 화면 사용 시간 추이(샘플).','mcm:csa/screenUsageStat',NULL,NULL,NULL,NULL,'N',600,'D','최근 14일 · 분','일별 화면 사용 시간','query-chart','Y',NULL,NULL,NULL);
